/*
 * A090893  Solutions x to equation floor(x*r*floor(x/r)) =
 *          floor(x/r*floor(x*r)) when r=sqrt(3).
 * https://oeis.org/A090893
 *
 * Offset:    0    (a(0) is the first term)
 * Keywords:  nonn
 * Formula:   not stated
 * Range:     u8 n <= 5, u16 n <= 25, u32 n <= 387, u64 n <= 5000,
 *            u128 n <= 5000, big any n
 * Helpers:   seq_isqrt
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

/* Sequence A090893 generated by testing the defining equality for successive integers. */

#include <stdlib.h>
#include <stdbool.h>
#include "../utils/seq_isqrt.h"

/* Test if an integer x satisfies  
   floor(x*sqrt(3)*floor(x/sqrt(3))) == floor((x/sqrt(3))*floor(x*sqrt(3)))   */
static inline bool is_solution(seq_t x)
{
    seq_t x2 = x * x;                                   /* x²            */
    seq_t f  = seq_isqrt((seq_t)3 * x2);                /* floor(x*√3)   */
    seq_t g  = seq_isqrt(x2 / (seq_t)3);                /* floor(x/√3)   */

    seq_t u = g * x;                                   /* g*x           */
    seq_t L = seq_isqrt((seq_t)3 * u * u);              /* LHS of equality */

    seq_t v = f * x;                                   /* f*x           */
    seq_t R = seq_isqrt(v * v / (seq_t)3);              /* RHS of equality */

    return L == R;
}

/* Cache to store the sequence to allow out‑of‑order calls. */
static seq_t *cache  = NULL;
static idx_t cache_len = 0;      /* number of terms stored */
static idx_t cache_cap  = 0;      /* allocated capacity */

/* Current integer being tested, the last value checked. */
static idx_t current_x = 0;

/* Ensure the cache has space for at least one more element. */
static void grow_cache(void)
{
    if (cache_len >= cache_cap) {
        cache_cap = cache_cap ? cache_cap * 2 : 8;
        seq_t *tmp = (seq_t *)realloc(cache, sizeof(seq_t) * cache_cap);
        if (!tmp) { /* allocation failure – shouldn't happen for the expected limits */
            exit(EXIT_FAILURE);
        }
        cache = tmp;
    }
}

/* Main sequence function. */
seq_t a(idx_t n)
{
    /* Initialise cache with a(0) = 0. */
    if (cache_len == 0) {
        cache_cap = 8;
        cache = (seq_t *)malloc(sizeof(seq_t) * cache_cap);
        cache[0] = (seq_t)0;
        cache_len = 1;
        current_x = 0;
    }

    /* Extend cache until we have a(n). */
    while (cache_len <= n) {
        current_x++;                     /* next integer to test */
        if (is_solution((seq_t)current_x)) {
            grow_cache();
            cache[cache_len++] = (seq_t)current_x;
        }
    }
    return cache[n];
}
